                yield "weekdayIds", (Encode.list JString) value.WeekdayIds
            ]
        )

    and decodeEventCondition (path: Path) (json: Json) : EventCondition =
        match Decode.discriminator path json with
        | "enterTile" -> EventCondition.EnterTile(decodeEnterTileCondition path json)
        | "interactTile" -> EventCondition.InteractTile(decodeInteractTileCondition path json)
        | "hasItem" -> EventCondition.HasItem(decodeHasItemCondition path json)
        | "inventorySpace" -> EventCondition.InventorySpace(decodeInventorySpaceCondition path json)
        | "flag" -> EventCondition.Flag(decodeFlagCondition path json)
        | "dayRange" -> EventCondition.DayRange(decodeDayRangeCondition path json)
        | "season" -> EventCondition.Season(decodeSeasonCondition path json)
        | "yearRange" -> EventCondition.YearRange(decodeYearRangeCondition path json)
        | "timeOfDay" -> EventCondition.TimeOfDay(decodeTimeOfDayCondition path json)
        | "questStatus" -> EventCondition.QuestStatus(decodeQuestStatusCondition path json)
        | "friendship" -> EventCondition.Friendship(decodeFriendshipCondition path json)
        | "weather" -> EventCondition.Weather(decodeWeatherCondition path json)
        | "festivalId" -> EventCondition.FestivalId(decodeFestivalIdCondition path json)
        | "variable" -> EventCondition.Variable(decodeVariableCondition path json)
        | "all" -> EventCondition.All(decodeAllCondition path json)
        | "any" -> EventCondition.Any(decodeAnyCondition path json)
        | "not" -> EventCondition.Not(decodeNotCondition path json)
        | "chance" -> EventCondition.Chance(decodeChanceCondition path json)
        | "scene" -> EventCondition.Scene(decodeSceneCondition path json)
        | "hearts" -> EventCondition.Hearts(decodeHeartsCondition path json)
        | "dayOfSeason" -> EventCondition.DayOfSeason(decodeDayOfSeasonCondition path json)
        | "relationship" -> EventCondition.Relationship(decodeRelationshipCondition path json)
        | "money" -> EventCondition.Money(decodeMoneyCondition path json)
        | "perk" -> EventCondition.Perk(decodePerkCondition path json)
        | "buff" -> EventCondition.Buff(decodeBuffCondition path json)
        | "skillLevel" -> EventCondition.SkillLevel(decodeSkillLevelCondition path json)
        | "mineFloor" -> EventCondition.MineFloor(decodeMineFloorCondition path json)
        | "collection" -> EventCondition.Collection(decodeCollectionCondition path json)
        | "bundle" -> EventCondition.Bundle(decodeBundleCondition path json)
        | "achievement" -> EventCondition.Achievement(decodeAchievementCondition path json)
        | "shipped" -> EventCondition.Shipped(decodeShippedCondition path json)
        | "building" -> EventCondition.Building(decodeBuildingCondition path json)
        | "slain" -> EventCondition.Slain(decodeSlainCondition path json)
        | "birthday" -> EventCondition.Birthday(decodeBirthdayCondition path json)
        | "weekday" -> EventCondition.Weekday(decodeWeekdayCondition path json)
        | other -> Decode.unknownDiscriminator path other

    and encodeEventCondition (value: EventCondition) : Json =
        match value with
        | EventCondition.EnterTile c -> encodeEnterTileCondition c
        | EventCondition.InteractTile c -> encodeInteractTileCondition c
        | EventCondition.HasItem c -> encodeHasItemCondition c
        | EventCondition.InventorySpace c -> encodeInventorySpaceCondition c
        | EventCondition.Flag c -> encodeFlagCondition c
        | EventCondition.DayRange c -> encodeDayRangeCondition c
        | EventCondition.Season c -> encodeSeasonCondition c
        | EventCondition.YearRange c -> encodeYearRangeCondition c
        | EventCondition.TimeOfDay c -> encodeTimeOfDayCondition c
        | EventCondition.QuestStatus c -> encodeQuestStatusCondition c
        | EventCondition.Friendship c -> encodeFriendshipCondition c
        | EventCondition.Weather c -> encodeWeatherCondition c
        | EventCondition.FestivalId c -> encodeFestivalIdCondition c
        | EventCondition.Variable c -> encodeVariableCondition c
        | EventCondition.All c -> encodeAllCondition c
        | EventCondition.Any c -> encodeAnyCondition c
        | EventCondition.Not c -> encodeNotCondition c
        | EventCondition.Chance c -> encodeChanceCondition c
        | EventCondition.Scene c -> encodeSceneCondition c
        | EventCondition.Hearts c -> encodeHeartsCondition c
        | EventCondition.DayOfSeason c -> encodeDayOfSeasonCondition c
        | EventCondition.Relationship c -> encodeRelationshipCondition c
        | EventCondition.Money c -> encodeMoneyCondition c
        | EventCondition.Perk c -> encodePerkCondition c
        | EventCondition.Buff c -> encodeBuffCondition c
        | EventCondition.SkillLevel c -> encodeSkillLevelCondition c
        | EventCondition.MineFloor c -> encodeMineFloorCondition c
        | EventCondition.Collection c -> encodeCollectionCondition c
        | EventCondition.Bundle c -> encodeBundleCondition c
        | EventCondition.Achievement c -> encodeAchievementCondition c
        | EventCondition.Shipped c -> encodeShippedCondition c
        | EventCondition.Building c -> encodeBuildingCondition c
        | EventCondition.Slain c -> encodeSlainCondition c
        | EventCondition.Birthday c -> encodeBirthdayCondition c
        | EventCondition.Weekday c -> encodeWeekdayCondition c
